"""Conway's Game of Life, with every generation computed by a GPU kernel.

Usage: uv run main.py <grid-file>

The grid file holds "<width> <height> <generations>" followed by height rows
of width digits (0 or 1) separated by single spaces. The final grid is written
to standard output in the same row format, followed by "ALIVE <count>".
"""

import array
import struct
import sys

import wgpu

MAX_DIM = 512
MAX_GENERATIONS = 1000
WORKGROUP = 16

SHADER = """
struct Params {
    width: u32,
    height: u32,
    pad0: u32,
    pad1: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(%(wg)d, %(wg)d)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    if (x >= params.width || y >= params.height) {
        return;
    }

    var neighbours = 0u;
    for (var dy: i32 = -1; dy <= 1; dy++) {
        for (var dx: i32 = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = i32(x) + dx;
            let ny = i32(y) + dy;
            if (nx >= 0 && ny >= 0 && nx < i32(params.width) && ny < i32(params.height)) {
                neighbours += src[u32(ny) * params.width + u32(nx)];
            }
        }
    }

    let index = y * params.width + x;
    let alive = src[index];
    var next = 0u;
    if (alive == 1u) {
        if (neighbours == 2u || neighbours == 3u) {
            next = 1u;
        }
    } else if (neighbours == 3u) {
        next = 1u;
    }
    dst[index] = next;
}
""" % {"wg": WORKGROUP}


def read_grid(path):
    with open(path, "r", encoding="utf-8") as handle:
        tokens = handle.read().split()
    if len(tokens) < 3:
        raise ValueError("header must hold width, height and generations")
    width, height, generations = (int(t) for t in tokens[:3])
    if not 1 <= width <= MAX_DIM or not 1 <= height <= MAX_DIM:
        raise ValueError(f"width and height must be between 1 and {MAX_DIM}")
    if not 0 <= generations <= MAX_GENERATIONS:
        raise ValueError(f"generations must be between 0 and {MAX_GENERATIONS}")

    # Digits are taken without regard to separators, so both the spaced
    # format and an unspaced run of digits are accepted.
    digits = "".join(tokens[3:])
    if len(digits) != width * height or set(digits) - {"0", "1"}:
        raise ValueError(f"expected {width * height} cells of 0 or 1")
    cells = [1 if c == "1" else 0 for c in digits]
    return width, height, generations, cells


def run_generations(width, height, generations, cells):
    """Advance the grid by the given number of generations on the GPU."""
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    if adapter is None:
        raise RuntimeError("no GPU adapter available")
    device = adapter.request_device_sync()

    cell_bytes = width * height * 4
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    buffers = [
        device.create_buffer(size=cell_bytes, usage=usage),
        device.create_buffer(size=cell_bytes, usage=usage),
    ]
    device.queue.write_buffer(buffers[0], 0, array.array("I", cells).tobytes())

    params = device.create_buffer_with_data(
        data=struct.pack("<4I", width, height, 0, 0),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": module, "entry_point": "main"},
    )
    layout = pipeline.get_bind_group_layout(0)

    # Generation g reads buffers[g % 2] and writes buffers[(g + 1) % 2].
    bind_groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": params.size}},
                {"binding": 1, "resource": {"buffer": buffers[i], "offset": 0, "size": cell_bytes}},
                {"binding": 2, "resource": {"buffer": buffers[1 - i], "offset": 0, "size": cell_bytes}},
            ],
        )
        for i in range(2)
    ]

    groups_x = (width + WORKGROUP - 1) // WORKGROUP
    groups_y = (height + WORKGROUP - 1) // WORKGROUP
    encoder = device.create_command_encoder()
    if generations > 0:
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        for generation in range(generations):
            compute.set_bind_group(0, bind_groups[generation % 2])
            compute.dispatch_workgroups(groups_x, groups_y, 1)
        compute.end()

    final = buffers[generations % 2]
    readback = device.create_buffer(
        size=cell_bytes,
        usage=wgpu.BufferUsage.MAP_READ | wgpu.BufferUsage.COPY_DST,
    )
    encoder.copy_buffer_to_buffer(final, 0, readback, 0, cell_bytes)
    device.queue.submit([encoder.finish()])

    readback.map_sync(wgpu.MapMode.READ)
    result = array.array("I")
    result.frombytes(bytes(readback.read_mapped()))
    readback.unmap()
    return list(result)


def format_grid(width, height, cells):
    lines = []
    for row in range(height):
        start = row * width
        lines.append(" ".join("1" if c else "0" for c in cells[start:start + width]))
    return lines


def main(argv):
    if len(argv) != 2:
        print("usage: main.py <grid-file>", file=sys.stderr)
        return 2

    try:
        width, height, generations, cells = read_grid(argv[1])
        cells = run_generations(width, height, generations, cells)
    except (OSError, ValueError, RuntimeError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1

    alive = sum(1 for c in cells if c)
    lines = format_grid(width, height, cells)
    lines.append(f"ALIVE {alive}")
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

